mapper.select:
/* selectMasterMdCdAgentCardManageList */ SELECT X.COM_CODE , X.COM_NAME_LOC , X.IRS_NO , X.INDUSTRY_TYPE , X.BUSINESS_ITEMS , X.CEO_NAME_LOC , X.ADDRESS_LOC , X.PRE_VISIT , X.THAT_VISIT , X.LST_VISIT_DATE FROM ( SELECT IC.COM_CODE , IC.COM_NAME_LOC , IC.IRS_NO , IC.INDUSTRY_TYPE , IC.BUSINESS_ITEMS , IC.CEO_NAME_LOC , IC.ADDRESS_LOC , (SELECT DECODE(COUNT(AGENT),0,'N','Y') FROM KEP_AGENT_VISIT AT WHERE AT.AGENT = IC.COM_CODE AND SUBSTR(AT.VISIT_DATE,0,6) = TO_CHAR(ADD_MONTHS(SYSDATE,-1), 'YYYYMM') AND AT.STATUS <> 'D') AS PRE_VISIT , (SELECT DECODE(COUNT(AGENT),0,'N','Y') FROM KEP_AGENT_VISIT AT WHERE AT.AGENT = IC.COM_CODE AND SUBSTR(AT.VISIT_DATE,0,6) = TO_CHAR(SYSDATE, 'YYYYMM') AND AT.STATUS <> 'D') AS THAT_VISIT , (SELECT MAX(AT.VISIT_DATE||AT.VISIT_TIME) FROM KEP_AGENT_VISIT AT WHERE AT.AGENT = IC.COM_CODE AND AT.STATUS <> 'D') AS LST_VISIT_DATE FROM ICOMCMPY IC WHERE 1=1 AND IC.BUSINESS_COND = 'S' AND IC.STATUS != 'D'
AND ( IC.COM_NAME_LOC LIKE '%'||#{st_agent_name}||'%'
OR
IC.COM_CODE = ( SELECT AGENT FROM KEP_AGENT_VISIT WHERE AGENT = 'KRKEPS0002' AND (VISIT_NOTE LIKE '%'||#{st_agent_name}||'%' OR AGENT_NAME LIKE '%'||#{st_agent_name}||'%') ) )
) X WHERE 1=1
AND X.PRE_VISIT = #{st_avisit_gbn}
AND X.THAT_VISIT = #{st_bvisit_gbn}
ORDER BY X.COM_NAME_LOC

/* selectMasterMdCdAgentCardManageVisitorList */ SELECT L.USER_ID AS CODE, L.USER_NAME_LOC AS TEXT1 FROM ICOMLUSR L WHERE L.COM_CODE = 'KRKORE0001' AND L.STATUS <> 'D' AND L.DEPARTMENT IN ('001','008','009','012','017','042','043','048','010') AND (L.OFFICE_YN IS NULL OR L.OFFICE_YN <> 'Y' )
AND L.DEPARTMENT = #{SEARCH1}
ORDER BY L.USER_NAME_LOC
